pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(actor != address(c) && actor != address(0));
        ts = bound(ts, 1, type(uint256).max);
        vm.warp(ts);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        bool ok;
        try c.fallback{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: on any successful 10-ether call at time ts, the stored
        // pastBlockTime is updated to ts (reference always; mutant never).
        assertTrue(!ok || c.pastBlockTime() == ts);
    }
}

