pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, uint256 bn) public {
        vm.assume(ts > bn);
        vm.warp(ts);
        vm.roll(bn);

        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call should succeed");

        // second call in the SAME block: reference must revert because
        // block.timestamp > pastBlockTime fails (pastBlockTime == block.timestamp)
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2, "second fallback call in the same block must revert");
    }
}

