// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 timestamp, uint256 blockNum, address actor) public {
        // keep the scenario in the admissible domain
        timestamp = bound(timestamp, pastBlockTime() + 1, type(uint256).max / 2);
        blockNum = bound(blockNum, 1, type(uint256).max / 2);
        vm.assume(actor != address(c) && actor != address(this));

        vm.warp(timestamp);
        vm.roll(blockNum);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        bool ok;
        (bool sent,) = address(c).call{value: 10 ether}("");
        ok = sent;

        // General rule: any completed fallback call either is a payout block
        // (number % 15 == 0), in which case the contract MUST have emptied its
        // balance, or it is not, in which case the balance is untouched by the
        // payout logic. The mutant skips the transfer, so on payout blocks its
        // balance remains positive.
        assertTrue(!(ok && blockNum % 15 == 0) || address(c).balance == 0);
    }

    uint256 storedAt;
    function pastBlockTime() internal view returns (uint256) { return address(c).balance == type(uint256).max ? 1 : readPast(); }
    function readPast() internal view returns (uint256) { return c.pastBlockTime(); }
}

contract Sender {
    C public target;
    constructor(C t) payable { target = t; }
    function hit() external { address(target).call{value: 10 ether}(""); }
}
}

