// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t, uint256 t2, address actor) public {
        vm.assume(t > 0);
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));

        // first call at time t
        vm.roll(1);
        vm.warp(t);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // second call at time t2, arbitrary but the rule must hold for all t2
        vm.roll(2);
        vm.warp(t2);
        vm.deal(actor, 10 ether);
        bool ok = true;
        vm.prank(actor);
        (bool sent, ) = address(c).call{value: 10 ether}("");
        ok = sent;

        // Rule: a call whose timestamp is not strictly greater than pastBlockTime must revert.
        // P satisfies this for every admissible input; M (>=) accepts a second call at the same timestamp.
        assertTrue(!ok || t2 > t, "second call at same-or-earlier timestamp must revert");
    }
}
